 16	
 17	var (
 18		exts = []string{".jpg", ".tif", ".tiff", ".png", ".pbm"}
 19	)
 20	
 21	func compareExt(ext string, exts []string) bool {
 22		for _, e := range exts {
 23			if ext == e {
 24				return true
 25			}
 26		}
 27		return false
 28	}
 29	
 30	func cleanupTemp(tmpDir string) {
 31		err := os.RemoveAll(tmpDir)
 32		if err != nil {
 33			log.Println(err)
 34		}
 35	}
 36	
 37	func ConvertPDFImages(path string) (BodyResult, error) {
 38		bodyResult := BodyResult{}
 39	
 40		tmp, err := ioutil.TempDir(os.TempDir(), "tmp-imgs-")
 41		if err != nil {
 42			bodyResult.err = err
 43			return bodyResult, err
 44		}
 45		tmpDir := fmt.Sprintf("%s/", tmp)
 46	
 47		defer cleanupTemp(tmpDir)
 48	
 49		_, err = exec.Command("pdfimages", "-j", path, tmpDir).Output()
 50		if err != nil {
 51			return bodyResult, err
 52		}
 53	
 54		filePaths := []string{}
 55	
 56		walkFunc := func(path string, info os.FileInfo, err error) error {
 57			path, err = filepath.Abs(path)
 58			if err != nil {
 59				return err
 60			}
 61	
 62			if compareExt(filepath.Ext(path), exts) {
 63				filePaths = append(filePaths, path)
 64			}
 65			return nil
 66		}
 67		filepath.Walk(tmpDir, walkFunc)
 68	
 69		fileLength := len(filePaths)
 70	
 71		if fileLength < 1 {
 72			return bodyResult, nil
 73		}
 74	
 75		var wg sync.WaitGroup
 76	
 77		data := make(chan string, fileLength)
 78	
 79		wg.Add(fileLength)
 80	
 81		for _, p := range filePaths {
 82			go func(pathFile string) {
 83				defer wg.Done()
 84				f, err := os.Open(pathFile)
 85				if err != nil {
 86					return
 87				}
 88	
 89				defer f.Close()
 90				out, _, err := ConvertImage(f)
 91				if err != nil {
 92					return
 93				}
 94	
 95				data <- out
 96	
 97			}(p)
 98		}
 99	
100		wg.Wait()

