package snapstate

import (
	"container/heap"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/snapcore/snapd/client"
	"github.com/snapcore/snapd/client/clientutil"
	"github.com/snapcore/snapd/overlord/assertstate"
	"github.com/snapcore/snapd/overlord/healthstate"
	"github.com/snapcore/snapd/overlord/snapstate"
	"github.com/snapcore/snapd/overlord/state"
	"github.com/snapcore/snapd/snap"

	"github.com/snapcore/snapd/overlord/privilege"
)

// A Heap is a priority queue for snapstate.SnapState by creation time.
// It's used to maintain the order of snapstates in the snap list.
// The heap is stored as a slice of state.SnapState.
type Heap []state.SnapState
func (h Heap) Len() int           { return len(h) }
func (h Heap) Less(i, j int) bool { return h[i].CreationTime.Before(h[j].CreationTime) }
func (h Heap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *Heap) Push(x interface{}) { *h = append(*h, x.(state.SnapState)) }
func (h *Heap) Pop() interface{}  { a := *h; h = &a; return a[len(a)-1] }

