def submit(self, data=None, files=None, **kwargs):
    """Submit a form."""
    if not self.is_form_valid:
        raise InvalidFormMethod("invalid form")

    # Handle files.
    if files:
        for name, value in files.items():
            self._send_file(name, value, False)
    else:
        # Send no files.
        return

    if data is None:
        data = self.get_current_form().form_data()
    else:
        data = self.get_current_form().form_data()
        data.update(data)

    # Send the form data.
    self._send_json(data, True)
    # Send the CSRF token.
    if self.csrf_token is not None:
        self._send_json({self.csrf_token_name: self.csrf_token}, True)
    # Send the HTTP method.
    if self.method in ('POST', 'PUT', 'PATCH'):
        self._send_http_method()
    self._send_cookies()
    self._send_headers()
    self._send_body()
    self._send_post()
    return self._check_for_redirects()

def _send_file(self, name, value, is_form):
    """Send a file as a form field."""
    if not is_form:
        return

    if not isinstance(name, str):
        name = str(name)
    if not isinstance(value, (str, bytes, os.PathLike)):
        value = str(value)
    if not os.path.isabs(value):
        value = os.path.normpath(os.path.join(self.base_dir, value))
    if not os.path.isfile(value):
        raise ValueError("File not found: %s" % value)
    self._send_json({name: os.path.basename(value)}, True)

def http_auth_domain(self, spider):
    """Return the domain for which the spider is allowed to receive credentials."""
    return getattr(spider, 'http_auth_domain', None) or ''

def process_request(self, request, spider):
    auth_domain = getattr(self, 'auth_domain', None)
    if auth_domain:
        request.headers[b'Authorization'] = 
            basic_auth_header(auth_domain, spider.http_user, spider.http_pass)

