const { auth, requiresAuth } = require('express-openid-connect');
app.use((req, res, next) => {
  if (req.path === '/.well-known/oauth2callback' ||
      req.path === '/.well-known/x509') {
    return next();
  }

  // Ensure the user is authenticated.
  if (!req.user) {
    return res.redirect('/');
  }

  // Ensure that the redirect is to a trusted domain.
  const domain = new URL(req.protocol === 'https' ? 'https://' : 'http://')
    .push(req.headers.host);
  if (req.headers.referer && req.headers.referer.indexOf(domain) !== -1) {
    return res.redirect(req.headers.referer);
  }

  // Redirect to the user's profile.
  return res.redirect(`/profile/${req.user.sub}`);
}};

